"use client";

import React, { useState, useMemo } from "react";
import { Calendar, ChevronDown, CheckCircle, AlertCircle, Clock } from "lucide-react";

// 1. Define Leave Types & Balances
const LEAVE_TYPES = [
  { id: "annual", label: "Annual Leave", balance: 24 },
  { id: "sick", label: "Sick Leave", balance: 15 },
  { id: "casual", label: "Casual Leave", balance: 7 },
  { id: "unpaid", label: "Loss of Pay", balance: 999 },
];

export default function RequestAbsencePage() {
  const [formData, setFormData] = useState({
    typeId: "annual",
    start: "",
    end: "",
    reason: "",
  });

  // 2. Intelligent Logic: Calculate Net Working Days (Excluding Weekends)
  const calculation = useMemo(() => {
    if (!formData.start || !formData.end) return { days: 0, error: null };
    
    const startDate = new Date(formData.start);
    const endDate = new Date(formData.end);
    
    if (endDate < startDate) return { days: 0, error: "End date cannot be before start date" };

    let count = 0;
    let cur = new Date(startDate);
    while (cur <= endDate) {
      const day = cur.getDay();
      if (day !== 0 && day !== 6) count++; // Skip Sun (0) and Sat (6)
      cur.setDate(cur.getDate() + 1);
    }

    const selectedType = LEAVE_TYPES.find(t => t.id === formData.typeId);
    if (selectedType && count > selectedType.balance) {
      return { days: count, error: `Insufficient ${selectedType.label} balance` };
    }

    return { days: count, error: null };
  }, [formData]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (calculation.error) return;
    alert(`Request submitted for ${calculation.days} days.`);
  };

  return (
    <div className="mx-auto max-w-4xl p-6 lg:p-12">
      {/* Header */}
      <div className="mb-10">
        <h1 className="text-3xl font-bold text-gray-900">Request Absence</h1>
        <p className="text-gray-500 mt-2">Submit your leave request for manager approval.</p>
      </div>

      <div className="grid grid-cols-1 gap-12 lg:grid-cols-5">
        {/* Left: The Form */}
        <form onSubmit={handleSubmit} className="lg:col-span-3 space-y-6">
          {/* Dropdown for Leave Type */}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-700">Leave Type</label>
            <div className="relative">
              <select
                value={formData.typeId}
                onChange={(e) => setFormData({ ...formData, typeId: e.target.value })}
                className="w-full appearance-none rounded-xl border border-gray-200 bg-white p-4 pr-12 text-sm focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
              >
                {LEAVE_TYPES.map((type) => (
                  <option key={type.id} value={type.id}>
                    {type.label} (Available: {type.balance})
                  </option>
                ))}
              </select>
              <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400 pointer-events-none" />
            </div>
          </div>

          {/* Date Range */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-semibold text-gray-700">Start Date</label>
              <input
                type="date"
                required
                className="w-full rounded-xl border border-gray-200 p-4 text-sm outline-none focus:border-blue-500"
                onChange={(e) => setFormData({ ...formData, start: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-semibold text-gray-700">End Date</label>
              <input
                type="date"
                required
                min={formData.start}
                className="w-full rounded-xl border border-gray-200 p-4 text-sm outline-none focus:border-blue-500"
                onChange={(e) => setFormData({ ...formData, end: e.target.value })}
              />
            </div>
          </div>

          {/* Reason */}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-700">Reason</label>
            <textarea
              required
              rows={4}
              placeholder="Provide a brief explanation..."
              className="w-full rounded-xl border border-gray-200 p-4 text-sm outline-none focus:border-blue-500"
              onChange={(e) => setFormData({ ...formData, reason: e.target.value })}
            />
          </div>

          <button
            type="submit"
            disabled={!!calculation.error || !formData.start}
            className="w-full rounded-xl bg-blue-600 py-4 font-bold text-white transition-all hover:bg-blue-700 active:scale-[0.98] disabled:bg-gray-200 disabled:text-gray-400 disabled:cursor-not-allowed"
          >
            Submit Request
          </button>
        </form>

        {/* Right: Real-time Summary Dashboard */}
        <div className="lg:col-span-2">
          <div className="rounded-3xl bg-gray-50 p-8 border border-gray-100">
            <h3 className="text-lg font-bold text-gray-900 mb-6">Request Summary</h3>
            
            <div className="space-y-6">
              <div className="flex justify-between items-center pb-4 border-b border-gray-200">
                <div className="flex items-center gap-3 text-gray-600">
                  <Clock className="h-5 w-5" />
                  <span className="text-sm">Duration</span>
                </div>
                <span className="font-bold text-gray-900">{calculation.days} Working Days</span>
              </div>

              <div className="flex justify-between items-center pb-4 border-b border-gray-200">
                <div className="flex items-center gap-3 text-gray-600">
                  <Calendar className="h-5 w-5" />
                  <span className="text-sm">Remaining</span>
                </div>
                <span className="font-bold text-blue-600">
                  {(LEAVE_TYPES.find(t => t.id === formData.typeId)?.balance || 0) - calculation.days} Days
                </span>
              </div>

              {/* Status/Error Messages */}
              {calculation.error ? (
                <div className="flex gap-3 rounded-2xl bg-red-50 p-4 text-red-700">
                  <AlertCircle className="h-5 w-5 shrink-0" />
                  <p className="text-xs font-semibold">{calculation.error}</p>
                </div>
              ) : formData.start && formData.end ? (
                <div className="flex gap-3 rounded-2xl bg-emerald-50 p-4 text-emerald-700">
                  <CheckCircle className="h-5 w-5 shrink-0" />
                  <p className="text-xs font-semibold">This request complies with company policy.</p>
                </div>
              ) : (
                <p className="text-xs text-gray-400 text-center italic">
                  Select dates to see the impact on your leave balance.
                </p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}